/*
 * THE SAVED FILTER, READ (TASK-L165 §4). PORTED: timeline-filter-store.ts.
 *
 * ONE OWNER OF THE KEY: this node reads it and `Save it` beside it writes it,
 * and nothing else in the template names it. ONE KEY FOR EVERY LEARNER: the
 * preference is about how the COACH works, not about the person on screen.
 *
 * Unknown members are DROPPED rather than kept: a kind renamed in the
 * vocabulary must not leave a saved filter matching nothing, which reads
 * exactly like an empty log. The vocabulary is `timeline.kind` — the same map
 * the chips and the cards take their words from — never a list kept beside it.
 *
 * Storage unavailable (a private window, a browser that blocks it) degrades to
 * "no saved filter", which is also what a first-time reader gets.
 */
function plain(x) {
  if (x === null || x === undefined) return x;
  if (Array.isArray(x)) return x.map(plain);
  if (typeof x === 'object') {
    if (typeof x.get === 'function' && x.data && typeof x.data === 'object') return plain(x.data);
    if (Array.isArray(x.items)) return plain(x.items);
    const out = {};
    for (const k of Object.keys(x)) out[k] = plain(x[k]);
    return out;
  }
  return x;
}
if (Inputs.copy === undefined || Inputs.copy === null) return;
const vocabulary = Object.keys(((plain(Inputs.copy) || {}).timeline || {}).kind || {});
let saved = [];
try {
  const raw = window.localStorage.getItem(Inputs.key);
  const parsed = raw ? JSON.parse(raw) : [];
  if (Array.isArray(parsed)) saved = parsed.filter((k) => vocabulary.indexOf(k) !== -1);
} catch (e) {
  saved = [];
}
/* The filter FIRST, then the flag: anything waiting on the flag must find the
   filter already there when it looks. */
Noodl.Variables.dbtFeedFilter = saved;
Noodl.Variables.dbtFeedFilterLoaded = true;

/*
 * THE SAVED FILTER, WRITTEN — the other half of the one owner. Only once the
 * saved value has been READ: writing before then would overwrite what the coach
 * chose last time with the empty array a page starts with.
 */
function plain(x) {
  if (x === null || x === undefined) return x;
  if (Array.isArray(x)) return x.map(plain);
  if (typeof x === 'object') {
    if (typeof x.get === 'function' && x.data && typeof x.data === 'object') return plain(x.data);
    if (Array.isArray(x.items)) return plain(x.items);
    const out = {};
    for (const k of Object.keys(x)) out[k] = plain(x[k]);
    return out;
  }
  return x;
}
if (Inputs.loaded !== true) return;
try {
  window.localStorage.setItem(Inputs.key, JSON.stringify(plain(Inputs.filter) || []));
} catch (e) {
  /* Storage full or unavailable — the filter keeps working in memory. */
}

/* A chip adds its kind or takes it away. `[]` is "everything" — there is one
   representation of unfiltered and no third state to get wrong. */
function plain(x) {
  if (x === null || x === undefined) return x;
  if (Array.isArray(x)) return x.map(plain);
  if (typeof x === 'object') {
    if (typeof x.get === 'function' && x.data && typeof x.data === 'object') return plain(x.data);
    if (Array.isArray(x.items)) return plain(x.items);
    const out = {};
    for (const k of Object.keys(x)) out[k] = plain(x[k]);
    return out;
  }
  return x;
}
const kind = String(Inputs.kind || '');
if (!kind) return;
const current = plain(Noodl.Variables.dbtFeedFilter) || [];
Noodl.Variables.dbtFeedFilter = current.indexOf(kind) !== -1 ? current.filter((k) => k !== kind) : current.concat([kind]);

/* Which rows are open is page state, NEVER saved: a log that remembered would
   come back as a wall one expansion at a time (L130). */
function plain(x) {
  if (x === null || x === undefined) return x;
  if (Array.isArray(x)) return x.map(plain);
  if (typeof x === 'object') {
    if (typeof x.get === 'function' && x.data && typeof x.data === 'object') return plain(x.data);
    if (Array.isArray(x.items)) return plain(x.items);
    const out = {};
    for (const k of Object.keys(x)) out[k] = plain(x[k]);
    return out;
  }
  return x;
}
const id = String(Inputs.id || '');
if (!id) return;
const open = plain(Noodl.Variables.dbtFeedOpen) || [];
Noodl.Variables.dbtFeedOpen = open.indexOf(id) !== -1 ? open.filter((x) => x !== id) : open.concat([id]);

/*
 * THE ACTIVITY LOG (TASK-L165 §4). PORTED: TimelineFeed.tsx.
 *
 * It ASSEMBLES NOTHING and ORDERS NOTHING: the rows arrive from
 * Logic/Ordered timeline in the model's order, already previewed. What this
 * decides is only what a log decides — which kinds are chips, which rows are
 * showing, which are open — and the words a coach reads beside them.
 */
function plain(x) {
  if (x === null || x === undefined) return x;
  if (Array.isArray(x)) return x.map(plain);
  if (typeof x === 'object') {
    if (typeof x.get === 'function' && x.data && typeof x.data === 'object') return plain(x.data);
    if (Array.isArray(x.items)) return plain(x.items);
    const out = {};
    for (const k of Object.keys(x)) out[k] = plain(x[k]);
    return out;
  }
  return x;
}
const fill = (t, v) => String(t || '').replace(/\{(\w+)\}/g, (m, k) => (k in v ? String(v[k]) : m));
if (Inputs.copy === undefined || Inputs.copy === null) return;
const copy = plain(Inputs.copy) || {};
const W = (copy.people || {}).learner;
if (!W) throw new Error('Logic/Feed filter: no people.learner copy');
const KIND = (copy.timeline || {}).kind || {};
const feed = plain(Inputs.feed);
if (!feed) return;
const filter = plain(Inputs.filter) || [];
const loaded = Inputs.loaded === true;
const open = new Set(plain(Inputs.open) || []);
const onProgramme = new Set((plain(Inputs.programmeRows) || []).map((r) => r.id));

/* ── BEING POINTED AT MEANS OPEN, AND VISIBLE FIRST (L138 §3) ──────────────
   The programme's "Show in the activity log" names a row here. Opening it is
   not enough on its own: the filter is remembered, so a jump can land on a row
   the filter has hidden and do nothing at all — L129's recorded trap. So the
   filter is cleared WHEN, AND ONLY WHEN, the target is hidden; clearing it
   every time would throw away a choice the coach made, for no reason.

   AND IT WAITS FOR THE SAVED FILTER. In the product the log is unmounted while
   the coach reads the programme, so a jump mounted it with the pointer already
   set while the saved filter was still being read: the first look saw `[]`,
   found the target "visible", opened it, and the filter landed a moment later
   and hid it again. Here the owner sits ABOVE both surfaces and reads storage
   once, at page load, so that ordering cannot arise — and the guard is kept
   anyway, because moving this node under a surface would bring it straight
   back and nothing would say so. `loaded` is its own value, never
   `filter.length`: "nothing saved" and "not read yet" are both `[]`. */
const focus = String(Inputs.focus || '');
if (focus && loaded) {
  const target = feed.find((r) => r.id === focus);
  if (target) {
    if (filter.length > 0 && filter.indexOf(target.kind) === -1) Noodl.Variables.dbtFeedFilter = [];
    if (!open.has(focus)) Noodl.Variables.dbtFeedOpen = Array.from(open).concat([focus]);
    Outputs.scrollSelector = '.dbt-entry-' + focus.replace(/[^A-Za-z0-9_-]/g, '_');
    Outputs.scroll();
  }
  /* Handed back, so pressing the same link twice works. Each write above re-runs
     this node with the new state, which is what renders it. */
  Noodl.Variables.dbtLogFocus = '';
  return;
}

/* A CHIP EXISTS ONLY FOR A KIND THIS PERSON HAS: a filter for a kind with no
   entries is a control that does nothing. In the vocabulary's order, which is
   the label map's — derived, never restated. NO COUNT ON A CHIP, EVER: "Signals
   7" is a tally of somebody's confusion presented as a number (TimelineFeed.tsx
   rejects it by name). And no chips at all for a person with one kind, because
   a filter that can only show everything is not a filter. */
const present = new Set(feed.map((r) => r.kind));
const kinds = Object.keys(KIND).filter((k) => present.has(k));
Outputs.hasChips = kinds.length > 1;
Outputs.chips = kinds.map((k) => {
  const on = filter.indexOf(k) !== -1;
  return {
    id: k,
    label: KIND[k],
    bg: on ? 'var(--primary)' : 'var(--surface-raised)',
    fg: on ? 'var(--primary-foreground)' : 'var(--foreground)',
    border: on ? 'var(--foreground)' : 'var(--border-subtle)'
  };
});
Outputs.showEverything = filter.length > 0;
Outputs.showEverythingLabel = W.log.showEverything;
Outputs.lede = W.log.lede;

const aboutText = (a) => {
  if (!a || !a.title && !a.anchorKind) return '';
  const what = a.anchorKind
    ? (a.title ? fill(W.log.aboutAnchored, { kind: W.log.anchorKind[a.anchorKind] || a.anchorKind, title: a.title }) : (W.log.anchorKind[a.anchorKind] || a.anchorKind))
    : a.title;
  return fill(W.log.about, { what: what });
};

const visible = filter.length === 0 ? feed : feed.filter((r) => filter.indexOf(r.kind) !== -1);
Outputs.rows = visible.map((r) => {
  const about = aboutText(r.about);
  return {
    id: r.id,
    kind: r.kind,
    className: 'dbt-feed-entry dbt-entry-' + r.id.replace(/[^A-Za-z0-9_-]/g, '_'),
    kindLabel: r.kindLabel,
    when: r.when || W.log.onPath,
    title: r.title,
    about: about,
    hasAbout: about !== '',
    open: open.has(r.id),
    body: r.body,
    hasBody: String(r.body || '').trim() !== '',
    /* Only where the thing it points at IS a row on their programme: a control
       with nothing behind it is worse than none (L142). */
    canJump: onProgramme.has(r.jumpTo),
    jumpTo: r.jumpTo,
    jumpLabel: W.log.showOnProgramme
  };
});
Outputs.hasRows = visible.length > 0;
Outputs.hasEmpty = visible.length === 0;
Outputs.emptyText = feed.length === 0 ? W.log.nothing : W.log.noneOfThat;
